import kp10_pages as KP
from htmlkit import native
JD = os.path.join(HERE, "out")
UNIT_ZH, UNIT_EN = "網路大小、泛化與早停", "Network size, generalization and early stopping"
TITLE_ZH = "圖型識別 第四章 KP10：網路大小、泛化與早停（大三）"; TITLE_EN = "Pattern Recognition, Chapter 4, KP10: network size, generalization and early stopping (undergraduate)"
NOTE_ZH = "教材程度：大學三年級（undergrad）。依講義 lec05-kp10 以 view-from-text-v3 製作：先規劃頁面，每頁以一張原生資訊圖（HTML 設計後轉成原生節點）為主，名詞在同一頁圖內定義。共 10 頁，所有數字皆由程式計算。第 1 頁的折線與第 3 頁的五個檢查點數字是教學示意與手編數字，不是網路訓練結果；第 8 頁的正弦示範設定是來源報告，沒有重跑。"
NOTE_EN = "Level: undergraduate (year 3). Made from the lecture lec05-kp10 with view-from-text-v3: pages were planned first and each page is mainly one native infographic (designed in HTML and converted to native nodes), with the terms defined on the same page. 10 pages; every number is computed by program. The polyline on page 1 and the five checkpoint numbers on page 3 are teaching illustrations and hand-made numbers, not network training results; the sine-demo setup on page 8 is the source's report and was not rerun."
def fig(n, alt_zh, alt_en):
    return lambda: native(f"kp10_p{n}", f"lec05-kp10-p{n}", KP.W, KP.H, JD, alt_en if os.environ.get("KP_LANG") == "en" else alt_zh)
P = []
NXT = {1: ("自由參數的計數", "counting free parameters"), 2: ("用驗證資料早停", "early stopping on validation data"), 3: ("三種資料的分工", "the roles of the three data sets"), 4: ("區域數上界", "the region-count bound"), 5: ("XOR 的明確構造", "the explicit XOR construction"), 6: ("三種選大小的策略", "the three sizing strategies"), 7: ("來源的正弦示範", "the source's sine demo"), 8: ("區域數的遞迴推導", "the region recursion"), 9: ("小練習", "the exercises")}
PREV = {2: ("背熟與學會", "memorizing versus learning"), 3: ("自由參數的計數", "counting free parameters"), 4: ("用驗證資料早停", "early stopping on validation data"), 5: ("三種資料的分工", "the roles of the three data sets"), 6: ("區域數上界", "the region-count bound"), 7: ("XOR 的明確構造", "the explicit XOR construction"), 8: ("三種選大小的策略", "the three sizing strategies"), 9: ("來源的正弦示範", "the source's sine demo"), 10: ("區域數的遞迴推導", "the region recursion")}
def add(n, lab, title, bridge, notes, alt):
    zh, en = notes
    if n in PREV: zh = f"承接上一頁的「{PREV[n][0]}」。" + zh; en = f"Following the previous page on {PREV[n][1]}. " + en
    if n == 1: zh = "這是 KP10 的第一頁。先備是損失與代價（KP06、KP09）、前向傳遞與參數（KP06）、超平面（KP03）。" + zh; en = "This is the first page of KP10. The prerequisites are loss and cost (KP06, KP09), forward pass and parameters (KP06) and hyperplanes (KP03). " + en
    if n == 10: zh += "到這裡這個單元就結束了；下一個 KP 是剪枝、正則化與模擬實證。"; en += " That ends this unit; the next KP covers pruning, regularization and simulations."
    if n in NXT: zh += f"接下來的下一頁是「{NXT[n][0]}」。"; en += f" Next, the next page covers {NXT[n][1]}."
    P.append(dict(lab=lab, title=title, bridge=bridge, notes=(zh, en), layout="freeform", spec=fig(n, *alt)))
add(1, ("背熟與學會", "Memorizing vs learning"),
    ("同一批帶雜訊的樣本：平滑規律才是學會，折線穿過每個點只是背熟了雜訊", "Same noisy samples: the smooth trend is learning, a polyline through every point memorizes noise"),
    ("訓練分數很高，新資料就一定也準嗎？控制網路大小，到底要避免什麼？", "Does a high training score mean new data is predicted well? What must controlling network size avoid?"),
    ("這一頁先分清背熟與學會。泛化是對沒參與訓練的新資料仍能正確預測，不是把原來的答案背熟。圖上黃點是 10 個帶雜訊的樣本，綠色是平滑規律 sin(2πx)，紅色虛線折線把每個點都穿過去：它背熟了雜訊，不是學到規律。這是連續預測的補充示意，折線不是網路訓練結果。分類也面臨同樣的取捨：先找主要規律，再看樣本的小波動，不必把每個波動都當成規律。控制網路大小，就是避免只背熟訓練資料。",
     "This page first separates memorizing from learning. Generalization means still predicting new data that was not used in training, not memorizing the original answers. The yellow dots are 10 noisy samples, the green curve is the smooth trend sin(2πx), and the red dashed polyline passes through every point: it memorized the noise instead of learning the pattern. This is a supplementary illustration for continuous prediction and the polyline is not a trained network. Classification faces the same trade-off: find the main pattern first, then look at the small wiggles; not every wiggle is a rule. Controlling network size means avoiding memorizing the training data."),
    ("帶雜訊的 10 個樣本、平滑曲線 sin(2πx) 與穿過每個點的折線；折線僅為教學示意。", "10 noisy samples, the smooth curve sin(2πx) and a polyline through every point; the polyline is only an illustration."))
add(2, ("自由參數", "Free parameters"),
    ("2–3–1 網路共 13 個自由參數：隱藏層 (2+1)×3 = 9、輸出層 (3+1)×1 = 4，不是只有 3 個單元", "A 2–3–1 network has 13 free parameters: hidden (2+1)×3 = 9, output (3+1)×1 = 4, not just 3 units"),
    ("折線背熟了雜訊，平滑曲線才是學會。網路到底有多少個可以調的數字？", "The polyline memorized the noise while the smooth trend is learning. How many adjustable numbers does a network actually have?"),
    ("這一頁數自由參數：訓練時可以獨立改變的數字，權重與偏置都算。例子是兩個輸入、三個隱藏單元、一個輸出，全部相連，每個計算單元有偏置。隱藏層每個單元有 2 個權重加 1 個偏置，(2 加 1) 乘 3 等於 9；輸出層有 3 個權重加 1 個偏置，(3 加 1) 乘 1 等於 4；總共 9 加 4 等於 13 個，不是只有三個隱藏單元（程式計算）。兩種相反的失敗：欠擬合是連主要規律都表達不好；過擬合是配合訓練資料的偶然細節，損害新資料的預測。較大不是過擬合的充分條件，資料量、權重大小、限制方式與訓練程序都會影響結果。",
     "This page counts free parameters: numbers that training can change independently, weights and biases both counting. The example has two inputs, three hidden units and one output, fully connected, with a bias in every computing unit. Each hidden unit has 2 weights plus 1 bias, (2 plus 1) times 3 equal to 9; the output has 3 weights plus 1 bias, (3 plus 1) times 1 equal to 4; in total 9 plus 4 equal to 13, not just the three hidden units (computed by program). Two opposite failures: underfitting cannot even express the main pattern; overfitting fits chance details of the training data and hurts predictions on new data. Larger is not sufficient for overfitting; data size, weight size, constraints and the training procedure all matter."),
    ("2–3–1 網路圖與參數計數：隱藏層 9 個、輸出層 4 個，共 13 個自由參數。", "A 2–3–1 network diagram with the parameter count: 9 in the hidden layer, 4 in the output layer, 13 free parameters."))
add(3, ("早停", "Early stopping"),
    ("驗證損失在第 3 輪最低（0.25），第 5 輪回升到 0.40：保留第 3 輪的權重，這就是早停", "Validation loss bottoms at 0.25 in epoch 3, then rises to 0.40: keep epoch 3 (early stopping)"),
    ("2–3–1 網路共有 13 個自由參數，架構固定了。訓練多久才好？", "A 2–3–1 network has 13 free parameters and the architecture is fixed. How long should we train?"),
    ("大小固定也可能過度配合訓練資料，所以要另外控制訓練時間。驗證集是不拿來更新權重、用來選模型或訓練檢查點的資料；過度訓練是架構固定，後續訓練開始追逐訓練集的細節，驗證表現反而惡化；早停是依驗證表現停止訓練並還原最佳檢查點，實作可以容許幾次沒改善。這是手編的教學數字，不是實驗結果：訓練損失 0.50、0.30、0.20、0.15、0.10，驗證損失 0.55、0.35、0.25、0.28、0.40。驗證損失最小是 0.25，在第 3 輪，保留第 3 輪的權重；第 5 輪訓練損失最低，驗證損失卻從 0.25 升到 0.40，增加 0.40 減 0.25 等於 0.15（程式計算）。兩條曲線不必相交，差距也不必從零開始。",
     "A fixed size can still overfit the training data, so training time must be controlled separately. The validation set is data not used to update weights, used to pick a model or a checkpoint; overtraining is when, with a fixed architecture, later training chases training-set details and validation performance worsens; early stopping stops training by validation performance and restores the best checkpoint, and implementations may allow a few non-improving checks. These are hand-made teaching numbers, not experimental results: training loss 0.50, 0.30, 0.20, 0.15, 0.10 and validation loss 0.55, 0.35, 0.25, 0.28, 0.40. The validation minimum is 0.25 at epoch 3, so keep the weights of epoch 3; epoch 5 has the lowest training loss, yet validation rose from 0.25 to 0.40, an increase of 0.40 minus 0.25 equal to 0.15 (computed by program). The two curves need not cross and the gap need not start at zero."),
    ("五個檢查點的訓練與驗證損失；驗證最低 0.25 在第 3 輪，第 5 輪回升到 0.40，訓練最低 0.10 在第 5 輪。", "Training and validation loss at five checkpoints; validation is lowest at 0.25 in epoch 3 and rises to 0.40 in epoch 5, while training is lowest at 0.10 in epoch 5."))
add(4, ("三種資料", "Three data sets"),
    ("訓練、驗證、測試：三種資料三個分工，測試集只在選完模型之後才用", "Training, validation, test: three data sets, three jobs; the test set only comes after model choice"),
    ("驗證損失在第 3 輪最低，保留第 3 輪權重。驗證資料用來選模型了，最後該用什麼資料報告成績？", "Validation loss bottoms at 0.25 in epoch 3, then rises to 0.40, so we keep epoch 3. With validation data used to choose, which data reports the final score?"),
    ("三種資料各司其職。訓練集用來更新權重、學到資料中的規律；驗證集用來選大小、懲罰強度及停止點，不直接更新權重；測試集在模型選完之後才做最後評估，反覆看它來挑模型就不再是獨立檢查，也要避免重複個體或時間資訊洩漏。小樣本的數字很粗：十筆中錯一筆，錯誤率 1 除以 10 等於 0.1；錯兩筆是 0.2，只差一個案例估計就差十個百分點（程式計算）。可用重複切分或交叉驗證輔助選擇，但每次仍須把訓練與評估分開，不能憑空增加獨立資料，所以沒有脫離資料量與任務的最佳神經元數。常見迷思：參數更少或訓練更久，並不各自保證新資料更準。",
     "The three data sets have separate jobs. The training set updates the weights and learns the pattern; the validation set chooses the size, penalty strength and stopping point and does not update weights directly; the test set is used for the final evaluation only after the model is chosen, and looking at it again and again to pick models ends its independence, while duplicate individuals or time information must not leak. Small-sample numbers are coarse: one error in ten is 1 over 10 equal to 0.1; two errors give 0.2, so one more case moves the estimate by ten percentage points (computed by program). Repeated splits or cross-validation can help, but training and evaluation stay separate each time and independent data cannot be created from nothing, so no best number of neurons exists apart from data size and task. Common myth: fewer parameters or longer training do not each guarantee better new-data accuracy."),
    ("訓練集、驗證集、測試集各自的用途與限制，以及小樣本錯 1 筆 0.1、錯 2 筆 0.2。", "The use and limits of the training, validation and test sets, and the small-sample error rates 0.1 for one error and 0.2 for two."))
add(5, ("區域數上界", "Region-count bound"),
    ("K 個超平面在 d 維最多切出 Σ C(K, m) 塊：d = 2、K = 3 最多 7 塊，維度越高增加越快", "K hyperplanes in d dimensions cut at most ΣC(K, m) regions: 7 for d = 2, K = 3, growing faster with d"),
    ("三種資料各司其職，測試集最後才用。能不能不訓練，直接從架構算出它的能力上限？", "The three data sets have separate jobs and the test set comes last. Can we compute an architecture's capacity limit without training?"),
    ("資料選擇回答預測好不好，幾何計數只回答架構最多能切出幾塊，兩者是不同的問題。用 K 個超平面切 d 維空間，區域數最多為 M_max(K, d) 等於 m 從 0 到 d 的 C(K, m) 總和；C(K, m) 是從 K 個挑 m 個的方法數，m 大於 K 時為 0。一般位置，也就是沒有重合、平行或多線共點，才可達此最大值。數值表：d 等於 1 時 K 從 1 到 4 是 2、3、4、5；d 等於 2 是 2、4、7、11；d 等於 3 是 2、4、8、15（程式計算）。例：d 等於 2、K 等於 2，1 加 2 加 1 等於 4，三個組合數分別是選 0、1、2 條線。圖上維度越高、線越多，最大區域數增加越快。",
     "Data choices answer whether predictions are good, while geometric counting only answers how many regions the architecture can cut at most; they are different questions. With K hyperplanes cutting d-dimensional space, the number of regions is at most M_max(K, d), the sum over m from 0 to d of C(K, m); C(K, m) is the number of ways to choose m of K and is 0 when m exceeds K. The maximum is reached only in general position, that is, with no coincident, parallel or concurrent hyperplanes. Value table: for d equal to 1 and K from 1 to 4 it is 2, 3, 4, 5; for d equal to 2 it is 2, 4, 7, 11; for d equal to 3 it is 2, 4, 8, 15 (computed by program). Example: d equal to 2 and K equal to 2 gives 1 plus 2 plus 1 equal to 4, the three binomials being choices of 0, 1 and 2 lines. In the chart, the higher the dimension and the more hyperplanes, the faster the maximum grows."),
    ("不同輸入維度 d 下 K = 1 到 6 個一般位置超平面的最大區域數曲線，與 d = 1 到 3、K = 1 到 4 的數值表。", "Curves of the maximum number of regions for K = 1 to 6 hyperplanes in general position at several input dimensions d, with the value table for d = 1 to 3 and K = 1 to 4."))
add(6, ("XOR 的構造", "XOR construction"),
    ("XOR：兩條平行線切成三條帶，兩個 A 點在中間帶；上界容得下，還要靠明確構造證明", "XOR: two parallel lines cut three bands with both A points in the middle; a construction proves it"),
    ("K 個超平面在 d 維最多切出 Σ C(K, m) 塊，d = 2、K = 3 最多 7 塊。XOR 的兩條線實際切成幾塊？", "K hyperplanes in d dimensions cut at most ΣC(K, m) regions, 7 for d = 2, K = 3. How many regions do XOR's two lines actually cut?"),
    ("XOR 的實際構造：KP01 的 x1 加 x2 等於 0.5 與 x1 加 x2 等於 1.5 兩條線平行，實際只切成三條帶。四個點的 x1 加 x2 分別是 (0,0) 為 0、(0,1) 與 (1,0) 為 1、(1,1) 為 2（程式計算）：0 小於 0.5，在下方帶，屬 B；1 在 0.5 與 1.5 之間，在中間帶，兩個 A 點住在這裡；2 大於 1.5，在上方帶，屬 B。四塊上界容得下三塊，只是容量檢查；兩個單元夠不夠，還要靠這個明確構造來證明。",
     "The explicit XOR construction: the KP01 lines x1 plus x2 equal to 0.5 and x1 plus x2 equal to 1.5 are parallel and actually cut only three bands. The sums x1 plus x2 at the four points are 0 at (0,0), 1 at (0,1) and (1,0), and 2 at (1,1) (computed by program): 0 is below 0.5, in the lower band, class B; 1 lies between 0.5 and 1.5, in the middle band where both A points live; 2 is above 1.5, in the upper band, class B. That four regions of the bound hold three is only a capacity check; whether two units suffice must be proved by this explicit construction."),
    ("兩條平行線 x₁ + x₂ = 0.5 與 1.5 把平面切成三條帶，兩個 A 點 (0,1)、(1,0) 在中間帶，兩個 B 點 (0,0)、(1,1) 在兩側帶。", "Two parallel lines x1 + x2 = 0.5 and 1.5 cut the plane into three bands; the A points (0,1) and (1,0) lie in the middle band and the B points (0,0) and (1,1) in the outer bands."))
add(7, ("三種策略", "Three strategies"),
    ("三種選大小的策略：解析法、剪枝、構造式方法，都要用驗證資料檢查", "Three ways to pick a size: analytic, pruning, constructive; all checked on validation data"),
    ("XOR 的兩條平行線切成三條帶，上界沒有告訴我們怎麼找到適合的大小。實際上有哪些策略？", "XOR's two parallel lines cut three bands, yet the bound does not say how to find a suitable size. Which strategies exist in practice?"),
    ("上界沒有告訴我們怎麼找到適合的大小。實際上有三種策略：解析法是用代數或統計分析估計能力，但通常忽略具體的最佳化過程；剪枝是先訓練較大的網路，再依規則刪掉較不重要的連線，下一個 KP 會講；構造式方法是從小架構逐步增加單元，KP05 已講過。三條路都需要用驗證資料檢查。",
     "The bound does not tell us how to find a suitable size. In practice there are three strategies: analytic methods estimate capability with algebra or statistics but usually ignore the actual optimization process; pruning trains a larger network first and then deletes the less important connections by a rule, which the next KP covers; constructive methods start from a small architecture and add units step by step, as KP05 showed. All three routes need checking on validation data."),
    ("解析法、剪枝、構造式方法三欄比較：解析法估計能力但忽略最佳化過程，剪枝先大後刪（下一個 KP），構造式從小架構加單元（KP05）；三者都要用驗證資料檢查。", "A three-column comparison: analytic methods estimate capability but ignore optimization, pruning trains large then deletes (next KP), constructive methods add units to a small architecture (KP05); all three are checked on validation data."))
add(8, ("正弦示範", "Sine demo"),
    ("來源的正弦示範：15 個訓練點、10 個測試點，k 個單元共 3k + 1 個參數；k 約 3 到 5 較合適", "The source's sine demo: 15 training and 10 test points, 3k + 1 parameters; k of about 3 to 5 suits"),
    ("三種策略都要用驗證資料檢查。來源的正弦示範用了什麼設定，結果能當成通用最佳值嗎？", "Three ways to pick a size (analytic, pruning, constructive) are all checked on validation data. What setup did the source's sine demo use, and is its result a universal optimum?"),
    ("來源有一個正弦示範，我們只說明它的設定，不把一次實驗當成通用最佳設定。目標是 y 等於 sin(2πx) 加 ε，ε 是加到觀測上的雜訊；資料是 15 個訓練點、10 個獨立測試點；模型是 ŷ 等於 j 從 1 到 k 的 v_j tanh(a_j x 加 b_j) 總和再加 c，k 是隱藏單元數，a_j、b_j、v_j、c 都可調，所以參數數是 3k 加 1：k 等於 3 是 10 個、k 等於 5 是 16 個、k 等於 15 是 46 個（程式計算）。來源描述 k 約 3 到 5 較合適、k 等於 15 可能過擬合。這不是任何資料的通用最佳值；本教材沒有重跑這個訓練。",
     "The source has a sine demo; we only describe its setup and do not treat one experiment as a general optimum. The target is y equal to sin(2πx) plus ε, where ε is noise added to the observations; the data are 15 training points and 10 independent test points; the model is ŷ equal to the sum over j from 1 to k of v_j tanh(a_j x plus b_j) plus c, where k is the number of hidden units and a_j, b_j, v_j and c are all adjustable, so the parameter count is 3k plus 1: 10 for k equal to 3, 16 for k equal to 5 and 46 for k equal to 15 (computed by program). The source describes k of about 3 to 5 as suitable and k equal to 15 as possibly overfitting. This is not a universal best value for any data, and the training was not rerun here."),
    ("正弦示範：15 個訓練點、10 個測試點；k = 3、5、15 時參數數為 10、16、46。", "The sine demo: 15 training and 10 test points; for k = 3, 5, 15 the parameter counts are 10, 16, 46."))
add(9, ("延伸：遞迴與程式", "Extension: recursion"),
    ("區域數的遞迴 R(K, d) = R(K−1, d) + R(K−1, d−1)：R(3, 2) = 4 + 3 = 7", "The region recursion R(K, d) = R(K−1, d) + R(K−1, d−1) gives R(3, 2) = 4 + 3 = 7"),
    ("來源正弦示範的 k 只是設定，不是通用最佳值。區域數上界的形式又是怎麼來的？", "The k in the source's sine demo is only a setting, not a universal optimum. Where does the form of the region bound come from?"),
    ("為什麼區域數是這個形式：在一般位置加入第 K 個超平面，它把原有某些區域切成兩半；新切出的部分，對應其他 K 減 1 個超平面在新平面內形成的低一維區域，所以 R(K, d) 等於 R(K 減 1, d) 加 R(K 減 1, d 減 1)，起點 R(0, d) 與 R(K, 0) 都是 1；利用 Pascal 關係得 C(K, m) 的總和。R(3, 2) 等於 R(2, 2) 加 R(2, 1) 等於 4 加 3 等於 7，與 1 加 3 加 3 一致（程式計算）。這個推導只計空間分割，不包含輸出層能否把任意區域標籤分對。右上是連續預測的平均平方誤差 L 等於 N 分之一乘誤差平方和，兩筆誤差 1 與負 1 得 1；分類另外要指定門檻與錯誤率。右下的程式只選已提供的檢查點，沒有訓練網路；真實訓練還要保存與還原該輪的權重、固定資料切分並記錄指標。",
     "Why the region count has this form: adding the K-th hyperplane in general position splits some existing regions in two; the new pieces correspond to the lower-dimensional regions that the other K minus 1 hyperplanes form inside the new plane, so R(K, d) equals R(K minus 1, d) plus R(K minus 1, d minus 1), starting from R(0, d) and R(K, 0) both equal to 1; Pascal's rule gives the sum of C(K, m). R(3, 2) equals R(2, 2) plus R(2, 1) equal to 4 plus 3 equal to 7, agreeing with 1 plus 3 plus 3 (computed by program). This derivation only counts space partitions and does not include whether the output layer can label any region correctly. Top right is the mean squared error L equal to one over N times the sum of squared errors for continuous prediction; errors 1 and minus 1 give 1; classification needs a threshold and an error rate separately. The code at the bottom right only selects among given checkpoints and trains no network; real training must also save and restore that epoch's weights, fix the data split and record the metric."),
    ("區域數遞迴與 R(3,2)=4+3=7 的驗算、均方誤差例子（誤差 1 與 −1 得 1），以及選檢查點的 Python 片段。", "The region recursion and the check R(3,2)=4+3=7, the mean-squared-error example (errors 1 and −1 give 1) and a Python snippet that selects a checkpoint."))
